/*commonRefPrNoPopup.buyerRefPrNoPopFORM1_v2*/
	SELECT
	 COD2.CODE
	 ,COD2.TEXT1
	 ,COD2.TEXT2
	FROM ICOMCOD2 COD2
	WHERE  COMPANY_CODE = #{st_buyer}
	AND TYPE = #{st_type}



	AND COD2.CODE = #{st_code}


	AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_text}||'%')


	AND COD2.TEXT4 = #{st_text4}


	AND FLAG = 'Y'


	AND COD2.TEXT3 = #{st_userDept}


	ORDER BY COD2.CODE


/*selectCost*/
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'C020'				
AND		FLAG = 'Y'
AND		COMPANY_CODE = #{st_buyer}
AND		CODE		 = #{st_code}


/*selectAccount*/
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'M014'
AND		FLAG = 'Y'
AND 	COMPANY_CODE = #{st_buyer}
AND		CODE		 = #{st_code}


/*selectPlant*/
SELECT	TEXT1
FROM	ICOMCOD2
